// src/game/mode.ts
var gameMode = {
  spectator: false,
  mapId: "riverlands",
  difficulty: "normal",
  mode: "skirmish",
  mutators: [],
  daily: null,
  op: null,
  opId: "",
  uncharted: false,
  party: false
};
var unchartedMatch = () => gameMode.uncharted && isRandomMapId(gameMode.mapId) && !gameMode.spectator && !gameMode.op && !gameMode.daily;
function activeMutators() {
  if (gameMode.op)
    return [];
  if (gameMode.daily)
    return gameMode.daily.mutators;
  if (gameMode.mode !== "skirmish")
    return [];
  const def = mapById(gameMode.mapId);
  return gameMode.mutators.filter((id) => !mapBansMutator(def, id));
}
var rematchToken = () => gameMode.party ? "party" : gameMode.op ? `op:${gameMode.op.id}` : gameMode.daily ? "daily" : gameMode.spectator && gameMode.mode !== "survival" ? "spectate" : "1";
