    const zoomK = CINE.zoom.mid / Math.exp(this.cam.lz);
    const dx = Math.sin(this.t * 0.37) * CINE.drift * zoomK;
    const dy = Math.cos(this.t * 0.27) * CINE.drift * 0.7 * zoomK;
    const c = this.cam;
    [c.x, c.vx] = spring(c.x, c.vx, this.aim.x + dx, CINE.panOmega, dt);
