    v.face += angleDelta2(v.face, u.facing) * turnK;
    v.aim = v.face;
    const sec = dtMs / 1000;
    const speed = sec > 0 ? moved / sec + Math.abs(angleDelta2(prevFace, v.face)) / sec * 0.12 : 0;
