    y: 0,
    z: 0,
    vx: 0,
    vy: 0,
    vz: 0,
    life: 1,
    t: 0,
    size0: 1,
    size1: 1,
    alpha0: 1,
    alpha1: 0,
    r: 1,
    g: 1,
    b: 1,
    r1: 1,
    g1: 1,
    b1: 1,
    tex: 0,
    rot: 0,
    spin: 0,
    gravity: 0,
    drag: 1,
    flat: false,
    fadeIn: 0,
    fadeFast: false,
    easeOut: false
