    if (owner && seen && !idle)
      g.fillStyle(col2, 0.05 + 0.03 * breathe).fillCircle(x, y, R);
    if (l.infantryOnly && !(owner === this.opts.player && l.crewed) && this.opts.dropReady?.())
      this.dropMarks(x, y, R);
