      ch[0].y = y + uy * d1 + ux * s;
      ch[1].x = x + ux * d0;
      ch[1].y = y + uy * d0;
      ch[2].x = x + ux * d1 + uy * s;
      ch[2].y = y + uy * d1 - ux * s;
