// src/ui/audio-panel.ts
var TOGGLES = [
  { id: "muted", icon: "\uD83D\uDD0A", label: "Sound" },
  { id: "music", icon: "\uD83C\uDFB5", label: "Music" },
  { id: "sfx", icon: "\uD83D\uDCA5", label: "Effects" },
  { id: "voice", icon: "\uD83D\uDDE3", label: "Voice" }
];
function mountAudioToggles(host) {
  host.classList.add("sound-row");
  host.setAttribute("role", "group");
  host.setAttribute("aria-label", "Sound settings");
  host.innerHTML = TOGGLES.map((t) => `<button class="snd" data-k="${t.id}" aria-pressed="false"><span class="si">${t.icon}</span><span class="sl">${t.label}</span></button>`).join("");
  const sync = () => {
    const s = sfx.settings;
    host.querySelectorAll(".snd").forEach((b) => {
      const k = b.dataset.k;
      const on = k === "muted" ? !s.muted : s[k];
      b.classList.toggle("on", on);
      b.classList.toggle("held", k !== "muted" && on && s.muted);
      b.setAttribute("aria-pressed", String(on));
      if (k === "muted")
        b.querySelector(".si").textContent = on ? "\uD83D\uDD0A" : "\uD83D\uDD07";
      if (k === "voice") {
        const chirps = on && !s.speech;
        b.querySelector(".sl").textContent = chirps ? "Chirps" : "Voice";
        b.querySelector(".si").textContent = chirps ? "\uD83E\uDD16" : "\uD83D\uDDE3";
        b.title = chirps ? "Unit chirps and radio codes, no speech (tap to turn off)" : on ? "Announcer speech and unit chirps (tap for chirps only)" : "Voice off (tap to turn on)";
      }
    });
  };
  host.querySelectorAll(".snd").forEach((b) => b.addEventListener("click", () => {
    const k = b.dataset.k;
    sfx.unlock();
    if (k === "muted")
      sfx.setMuted(!sfx.muted);
    else if (k === "voice") {
      const s = sfx.settings;
      if (!s.voice) {
        sfx.setSpeech(true);
        sfx.setChannel("voice", true);
      } else if (s.speech)
        sfx.setSpeech(false);
      else
        sfx.setChannel("voice", false);
      if (sfx.settings.voice) {
        voices.say("stinger", "select", 7);
        radioCheck();
      }
      return;
    } else
      sfx.setChannel(k, !sfx.settings[k]);
    sfx.play("click", 0.5);
  }));
  sync();
  return sfx.onChange(sync);
}

