    const b = typeof B[k] === "number" ? B[k] : 0;
    if (typeof A[k] !== "number" && typeof B[k] !== "number")
      continue;
    if (!Number.isFinite(a) || !Number.isFinite(b) || a === 0 && b === 0)
      continue;
