    pov: ctx.pov,
    won: ctx.won,
    duration: ctx.secs,
    difficulty: duel ? "" : ctx.enemy.difficulty.toLowerCase(),
    built: c.built,
    firstBuilt: c.firstBuilt,
    deaths: c.deaths,
    samples: c.samples,
