var escapeHtml = (s) => s.replace(/[&<>"]/g, (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[ch]);
function showReport(endEl, o) {
  const chronicle = chronicleOf(o.world);
  chronicle.finish();
  const ctx = {
    ...o,
    chronicle,
    won: !o.spectator && o.winner === o.pov,
    mvp: chronicle.mvp(),
    moments: moments(chronicle, o.spectator ? null : o.pov)
  };
  const builtIn = [
    { id: "chart", order: 10, col: "left", render: chartHtml },
    { id: "moments", order: 20, col: "left", render: momentsHtml },
    { id: "mvp", order: 30, render: (c) => mvpRowHtml(c.world, c.mvp, c.pov, c.spectator) },
    { id: "stats", order: 40, render: statsHtml },
    { id: "tip", order: 50, render: tipHtml }
  ];
  const sections = [...builtIn, ...extraSections].sort((a, b) => a.order - b.order);
  const rendered = [];
  for (const s of sections) {
    let html = null;
    try {
      html = s.render(ctx);
    } catch (e) {
      console.warn("report section failed:", s.id, e);
    }
    if (html)
      rendered.push({ s, html });
  }
  let delay = 120;
  const block = (r) => {
    delay += 110;
    return `<section class="aar-sec sec-${r.s.id}" data-id="${r.s.id}" style="--d:${delay}ms">${r.html}</section>`;
  };
  const left = rendered.filter((r) => r.s.col === "left").map(block).join("");
  const right = rendered.filter((r) => r.s.col !== "left").map(block).join("");
  endEl.hidden = false;
  const button = (a) => `<button id="${a.id}" class="cta ${a.cls ?? ""}">${escapeHtml(a.label)}</button>`;
  endEl.innerHTML = `
    <div class="panel aar ${ctx.spectator ? "spec" : ctx.winner === "draw" || ctx.winner === null ? "draw" : ctx.won ? "won" : "lost"}">
      <header class="aar-sec aar-head" style="--d:0ms">${headHtml(ctx)}</header>
      <div class="aar-cols"><div class="aar-col l">${left}</div><div class="aar-col r">${right}</div></div>
      <div class="aar-actions${o.actions?.length || o.after?.length ? " more" : ""}">
        ${(o.actions ?? []).map(button).join("")}
        <button id="again" class="cta${o.actions?.length ? " alt" : ""}">${escapeHtml(o.rematchLabel ?? "↻ Rematch")}</button>
        ${(o.after ?? []).map(button).join("")}
        <button id="menu" class="cta alt">Main menu</button>
      </div>
    </div>`;
  endEl.querySelectorAll(".aar-moments li").forEach((li) => {
    const m = ctx.moments[Number(li.dataset.i)];
    const mx = li.querySelector(".mx");
    if (m && mx)
      mx.textContent = m.text;
  });
  const select = (i) => {
    endEl.querySelectorAll(".aar-moments li").forEach((li) => li.classList.toggle("on", Number(li.dataset.i) === i));
    endEl.querySelectorAll(".aar-svg .mk").forEach((g) => g.classList.toggle("on", Number(g.dataset.i) === i));
  };
  const chartEl = endEl.querySelector(".sec-chart");
  if (chartEl)
    mountChart(chartEl, ctx, select);
  endEl.querySelectorAll(".aar-moments li").forEach((li) => li.addEventListener("click", () => {
    const i = Number(li.dataset.i);
    select(li.classList.contains("on") ? null : i);
  }));
  for (const r of rendered) {
    const el = endEl.querySelector(`.aar-sec[data-id="${r.s.id}"]`);
    if (el && r.s.mount)
      r.s.mount(el, ctx);
  }
  for (const a of [...o.actions ?? [], ...o.after ?? []])
    endEl.querySelector(`#${a.id}`)?.addEventListener("click", a.on);
  endEl.querySelector("#again").addEventListener("click", o.onRematch);
  endEl.querySelector("#menu").addEventListener("click", o.onMenu);
}

// src/ui/career.ts
var esc = (s) => s.replace(/[&<>"]/g, (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[ch]);
var fmt = (n2) => Math.round(n2).toLocaleString("en-US");
var mapName = (id) => {
  const def2 = mapById(id);
  return def2.id === id ? def2.name : id;
};
var diffName = (d) => DIFFICULTY[d]?.label ?? d;
function starPath(cx, cy, r) {
  let d = "";
  for (let i = 0;i < 10; i++) {
    const a = Math.PI / 5 * i - Math.PI / 2;
    const rr = i % 2 === 0 ? r : r * 0.45;
    d += `${i === 0 ? "M" : "L"}${(cx + Math.cos(a) * rr).toFixed(2)},${(cy + Math.sin(a) * rr).toFixed(2)}`;
  }
  return `${d}Z`;
}
function insigniaSvg(index) {
  const tier = index <= 3 ? "enl" : index <= 5 ? "off" : "cmd";
  const col2 = tier === "enl" ? "#e0a75e" : tier === "off" ? "#d5deec" : "#ffd66e";
  let inner = "";
  if (index === 0)
    inner = `<circle cx="20" cy="20" r="4" fill="${col2}"/>`;
  else if (index <= 3)
    for (let i = 0;i < index; i++) {
      const y = 12 + i * 6.5 + (3 - index) * 3.2;
      inner += `<path d="M11 ${y} L20 ${y + 6} L29 ${y}" fill="none" stroke="${col2}" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round"/>`;
    }
  else if (index <= 5)
    for (let i = 0;i < index - 3; i++) {
      const y = (index === 4 ? 18 : 14.5) + i * 7;
      inner += `<rect x="12" y="${y}" width="16" height="4" rx="1.2" fill="${col2}"/>`;
    }
  else {
    const n2 = index - 5;
    const spots = [
      [[20, 20, 8.5]],
      [[13.5, 20, 6], [26.5, 20, 6]],
      [[11.5, 22, 5], [20, 15.5, 5], [28.5, 22, 5]],
      [[14, 15, 5], [26, 15, 5], [14, 26, 5], [26, 26, 5]]
    ];
    for (const [x, y, r] of spots[n2 - 1])
      inner += `<path d="${starPath(x, y, r)}" fill="${col2}"/>`;
  }
  return `<svg class="insignia ${tier}" viewBox="0 0 40 40" aria-hidden="true">
    <path d="M20 2 L36 8 V20 C36 30 28.5 35.5 20 38.5 C11.5 35.5 4 30 4 20 V8 Z" class="ins-shield"/>${inner}</svg>`;
}
function starsText(mask) {
  return [1, 2, 4].map((b) => mask & b ? "★" : "☆").join("");
}
function rankBadgeHtml(c) {
  const r = rankOf(c.xp);
  const medals = MEDAL_IDS.reduce((n2, id) => n2 + (c.medals[id] ? 1 : 0), 0);
  const xpLine = r.next === null ? `${fmt(c.xp)} XP · top rank` : `${fmt(c.xp)} / ${fmt(r.next)} XP`;
  return `${insigniaSvg(r.index)}
    <span class="rb-t"><b>${r.name}</b><span class="rb-xp">${xpLine}</span></span>
    <span class="rb-medals" title="Medals earned">\uD83C\uDFC5 ${medals}/${MEDAL_IDS.length}</span>
    <span class="rb-bar"><i style="width:${(r.progress * 100).toFixed(1)}%"></i></span>`;
}
function dailyHtml(op, c) {
  const day = today();
  const streak = currentStreak(c, day);
  const wonToday = c.daily.lastWin === op.day;
  const muts = op.mutators.map((id) => `<span class="dl-mut">${MUTATORS[id].icon} ${MUTATORS[id].name}</span>`).join("");
  return `
    <div class="dl-head">
      <span class="dl-tag">\uD83D\uDCC5 Daily Op #${op.number}</span>
      <span class="dl-date">${op.label}</span>
      <span class="dl-streak${streak > 0 ? " hot" : ""}" title="Daily Op win streak">\uD83D\uDD25 ${streak}</span>
    </div>
    <div class="dl-body">
      <img src="${mapAssetBase(op.mapId)}/thumb.webp" alt="" draggable="false"/>
      <div class="dl-what">
        <b>${mapName(op.mapId)}</b>
        <span class="dl-vs">vs ${STRATEGIES[op.strategy].label} · <i class="${op.difficulty}">${diffName(op.difficulty)}</i></span>
      </div>
      <button class="dl-play${wonToday ? " done" : ""}" id="dl-play">${wonToday ? "✓ Won<small>replay</small>" : "▶ Play"}</button>
      <span class="dl-muts">${muts}</span>
    </div>`;
}
function mutButtonHtml() {
  const on = gameMode.mutators;
  if (on.length === 0)
    return `<span class="mb-k">\uD83E\uDDEA Mutators</span><span class="mb-v">Off</span>`;
  const def2 = mapById(gameMode.mapId);
  const names = on.map((id) => mapBansMutator(def2, id) ? `<s>${MUTATORS[id].icon} ${MUTATORS[id].name}</s>` : `${MUTATORS[id].icon} ${MUTATORS[id].name}`).join(" · ");
  const live = on.some((id) => !mapBansMutator(def2, id));
  return `<span class="mb-k">\uD83E\uDDEA</span><span class="mb-v on">${names}</span>${live ? `<span class="mb-n">no stars</span>` : ""}`;
}
function mountMenuCareer(menu, hooks) {
  let career = loadCareer();
  const op = dailyOp(today());
  const badge = menu.querySelector("#rankbadge");
  const daily = menu.querySelector("#dailyop");
  const mutBtns = [...menu.querySelectorAll(".mutbtn")];
  const sync = () => {
    career = loadCareer();
    if (badge)
      badge.innerHTML = rankBadgeHtml(career);
    for (const b of mutBtns) {
      b.innerHTML = mutButtonHtml();
      b.classList.toggle("on", gameMode.mutators.length > 0);
      b.hidden = gameMode.mode !== "skirmish";
    }
  };
  if (daily) {
    daily.innerHTML = dailyHtml(op, career);
    daily.querySelector("#dl-play")?.addEventListener("click", () => hooks.playDaily(op));
  }
  badge?.addEventListener("click", () => {
    sfx.play("click", 0.5);
    showCareerSheet(menu, career);
  });
  for (const b of mutBtns)
    b.addEventListener("click", () => {
      sfx.play("click", 0.5);
      showMutatorSheet(menu, () => {
        sync();
        hooks.changed();
      });
    });
  sync();
  return {
    sync,
    starsFor: (mapId) => career.stars[recordKey(mapId, gameMode.difficulty)] ?? 0
  };
}
function openSheet(host, cls, html) {
  host.querySelector(".sheet-wrap")?.remove();
  const wrap = document.createElement("div");
  wrap.className = "sheet-wrap";
  wrap.innerHTML = `<div class="sheet ${cls}" role="dialog">${html}</div>`;
  host.appendChild(wrap);
  const close = () => wrap.remove();
  wrap.addEventListener("click", (e) => {
    if (e.target === wrap)
      close();
  });
  wrap.querySelectorAll(".sheet-close").forEach((b) => b.addEventListener("click", close));
  return wrap;
}
function showMutatorSheet(host, onDone) {
  const def2 = mapById(gameMode.mapId);
  const chips = MUTATOR_IDS.map((id) => {
    const m = MUTATORS[id];
    const on = gameMode.mutators.includes(id);
    const why = mapBansMutator(def2, id);
    return `<button class="mutchip${on ? " on" : ""}${why ? " blocked" : ""}" data-id="${id}" aria-pressed="${on}">
      <em>${m.icon}</em><b>${m.name}</b><small>${why ?? m.desc}</small></button>`;
  }).join("");
  const wrap = openSheet(host, "mutsheet", `<h2>\uD83E\uDDEA Mutators</h2>
     <p class="sh-sub">Twist the rules of your next skirmish. Both sides play by them.</p>
     <div class="mutgrid">${chips}</div>
     <p class="sh-note">Mutated matches earn XP and medals but no map stars.</p>
     <div class="sh-actions"><button class="cta alt" id="mut-clear">Clear all</button><button class="cta sheet-close" id="mut-done">Done</button></div>`);
  const refresh = () => wrap.querySelectorAll(".mutchip").forEach((el) => {
    const on = gameMode.mutators.includes(el.dataset.id);
    el.classList.toggle("on", on);
    el.setAttribute("aria-pressed", String(on));
  });
  wrap.querySelectorAll(".mutchip").forEach((el) => el.addEventListener("click", () => {
    if (el.classList.contains("blocked") && !gameMode.mutators.includes(el.dataset.id))
      return;
    gameMode.mutators = toggleMutator(gameMode.mutators, el.dataset.id);
    sfx.play("click", 0.5);
    refresh();
    onDone();
  }));
  wrap.querySelector("#mut-clear").addEventListener("click", () => {
    gameMode.mutators = [];
    refresh();
    onDone();
  });
}
