function shroudRects(vis, W, H, S3) {
  const k = S3 / W;
  const out = [];
  for (let ty = 0;ty < H; ty++) {
    const y0 = Math.floor(ty * k);
    const y1 = Math.ceil((ty + 1) * k);
    for (let tx = 0;tx < W; ) {
      if (vis[ty * W + tx] !== 0 /* Unexplored */) {
        tx++;
        continue;
      }
      const run = tx;
      while (tx < W && vis[ty * W + tx] === 0 /* Unexplored */)
        tx++;
      const x0 = Math.floor(run * k);
      out.push(x0, y0, Math.ceil(tx * k) - x0, y1 - y0);
    }
  }
  return out;
}
