  fc = new Uint8Array([255, 255, 255, 255]);
  lift;
  sx = new Float64Array(256);
  sy = new Float64Array(256);
  sn = 0;
  dx = new Float64Array(256);
  dz = new Float64Array(256);
  off = new Float64Array(6);
  pc = new Uint8Array(24);
