  ctx.moveTo(x - 9 * k, y - 2 * k);
  ctx.lineTo(x, y - 6.5 * k);
  ctx.lineTo(x + 9 * k, y - 2 * k);
  ctx.lineTo(x + 9 * k, y + 4 * k);
  ctx.lineTo(x, y - 0.5 * k);
