    wrap.querySelector(".mp-meta").innerHTML = `<b>#${esc3(info?.code ?? "")}</b> · ${BIOME_ICON[d.biome]} ${cap(d.biome)}` + (info ? ` · ${esc3(cap(info.layout.replace(/-/g, " ")))}` : "") + ` · ${d.size}×${d.size}`;
