  panel.el.querySelector(".pp-prev").textContent = "‹";
  panel.el.querySelector(".pp-next").textContent = "›";
  if (s.pending)
    panel.el.querySelector(".pp-note").textContent = s.pending.ready ? `${s.pending.name} going up` : `${s.pending.name}: ${s.pending.left}s`;
